import { motion } from 'framer-motion';
import profile from '../assets/pic.jpg';
export default function Hero() {
  return (

    <motion.section

      initial={{ opacity: 0, x: -50 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ duration: 0.6 }}
      className="text-center px-4 pt-10"
    >
      {/* Profile Photo */}
      <div id="hero"  className="mx-auto mb-6 w-48 h-48 md:w-56 md:h-56 rounded-full overflow-hidden border-4 border-gray-500 -mt-12">
        <img
          src={profile}
          alt="Abdul Razack"
          className="w-full h-full object-cover"
        />
      </div>

      {/* Name */}
      <h1 className="text-4xl md:text-5xl font-bold mb-4 text-gray-900 dark:text-white">
        Hi, I'm Abdul Razack
      </h1>

      {/* Intro Paragraph */}
           {/* Intro Paragraph */}
      <p className="text-lg md:text-xl text-gray-600 dark:text-gray-300 max-w-6xl mx-auto mb-6">
        I build modern, scalable web applications with a focus on clean UI, performance, and great user experience. 
        I enjoy turning real business requirements into responsive, reliable products.
      </p>

      {/* Experience Paragraph */}
      <p className="text-lg md:text-xl text-gray-600 dark:text-gray-300 max-w-6xl mx-auto">
        <span className="font-bold">At Numerique360</span>, I worked on live production projects across ERP systems and dashboards, contributing to UI development, API integration, performance improvements, and ongoing maintenance—delivering polished features with a strong attention to detail.
      </p>

    </motion.section>
  );
}
